/**
 * Part numbers of the part table (`parts.mjs`), and which colours each part
 * was really made in.
 *
 * LDraw part numbers are used everywhere in the app (export, the colour
 * table's keys). Rebrickable's number is the same string except where the
 * part table gives `rb` (the inverted slopes: LDraw names the current mould,
 * Rebrickable folds the moulds together); the parts-list CSV and Rebrickable
 * links use `rebrickableId`. Colours: see palette.mjs (`rb` per colour).
 *
 * Availability comes from `src/data/availability.json`, generated by
 * `tools/availability.mjs` from Rebrickable's set inventories.
 */

import AVAILABILITY from '../data/availability.json' with { type: 'json' };
import { PALETTE } from './palette.mjs';
import { PART_TYPES, SLOPES, footprintKey, partType, typeOfFootprint } from './parts.mjs';
import { ALWAYS_ALLOWED } from './stock.mjs';

/**
 * LDraw part number by shape key `<kind>:<short>x<long>` for the bricks,
 * plates and tiles, in size order (narrow first, then short first). Slopes
 * carry their own `ldraw`. Derived from the part table (`parts.mjs`).
 */
export const LDRAW_IDS = Object.fromEntries(
  ['brick', 'plate', 'tile'].flatMap((kind) =>
    PART_TYPES.filter((p) => p.kind === kind && !p.round)
      .sort((a, b) => a.w - b.w || a.d - b.d)
      .map((p) => [footprintKey(kind, p.w, p.d), p.ldraw]),
  ),
);

/** LDraw numbers of the slopes `slopes.mjs` places (not the inverted ones). */
export const SLOPE_IDS = SLOPES.map((s) => s.ldraw);

/** LDraw numbers of every part in the table. */
export const PART_IDS = PART_TYPES.map((p) => p.ldraw);

/** Shape key of a brick, plate or tile (footprint short side first). */
export function shapeKey(part) {
  return footprintKey(part.kind, part.w, part.d);
}

/** LDraw part number of a placed part. */
export function ldrawId(part) {
  const type = partType(part);
  if (!type) throw new Error(`no part number for ${shapeKey(part)}`);
  return type.ldraw;
}

/** Rebrickable's number of a placed part (parts-list CSV, links). */
export function rebrickableId(part) {
  const type = partType(part);
  if (!type) throw new Error(`no part number for ${shapeKey(part)}`);
  return type.rb ?? type.ldraw;
}

/**
 * Evidence that (part, colour) was really made: `{ sets, lastYear, element }`
 * -- how many official sets contain it, the newest such set's year, and
 * whether LEGO gave it an element id. Null when there is no evidence at all.
 */
export function availability(ldraw, code) {
  const entry = AVAILABILITY.parts[ldraw]?.[code];
  return entry ? { sets: entry[0], lastYear: entry[1], element: entry[2] === 1 } : null;
}

/** True when the part was made in that colour (in a set, or with an element id). */
export function isMade(ldraw, code) {
  return availability(ldraw, code) !== null;
}

/**
 * The stock a build is limited to ("only use the parts I have", core/stock.mjs),
 * or null. Set by `buildModel` for the length of one synchronous build and
 * cleared after it (`withStock`), so the stages need no extra argument and
 * nothing outside a build sees it.
 * @type {import('./stock.mjs').Stock | null}
 */
let buildStock = null;

/** Parts allowed whatever the stock holds, so every cell can be filled (stock.mjs ALWAYS_ALLOWED). */
const FILLERS = ALWAYS_ALLOWED;

/**
 * Run `fn` with the catalog limited to a stock: a part counts as available
 * only when it was made in that colour and the stock has at least one, except
 * the 1×1 brick and plate (FILLERS).
 * @template T
 * @param {import('./stock.mjs').Stock | null} stock
 * @param {() => T} fn
 * @returns {T}
 */
export function withStock(stock, fn) {
  const before = buildStock;
  const next = stock ?? null;
  if (next === before) return fn();
  buildStock = next;
  shapeLists.clear();
  try {
    return fn();
  } finally {
    buildStock = before;
    shapeLists.clear();
  }
}

/**
 * True when the part can be used in that colour: it was made in it and, while
 * a build is limited to a stock (`withStock`), the stock has it.
 */
export function isAvailable(ldraw, code) {
  if (!isMade(ldraw, code)) return false;
  return !buildStock || FILLERS.has(ldraw) || (buildStock.parts[ldraw]?.[code] ?? 0) > 0;
}

/** Same check for a placed part (`color` is palette index + 1): was it made in that colour? */
export function partAvailable(part) {
  return isMade(ldrawId(part), PALETTE[part.color - 1].code);
}

/** True when a brick, plate or tile of footprint w × d exists in palette colour `color` (index + 1). */
export function shapeAvailable(kind, w, d, color) {
  const type = typeOfFootprint(kind, w, d);
  return type !== undefined && isAvailable(type.ldraw, PALETTE[color - 1].code);
}

/** Per shape list, per colour: the shapes that exist in that colour (cached; lists are module constants). */
const shapeLists = new Map();

/** The shapes of `shapes` that exist in palette colour `color`, in the same order. */
export function availableShapes(shapes, color) {
  let byColour = shapeLists.get(shapes);
  if (!byColour) shapeLists.set(shapes, (byColour = new Map()));
  let list = byColour.get(color);
  if (!list) byColour.set(color, (list = shapes.filter((s) => shapeAvailable(s.kind, s.w, s.d, color))));
  return list;
}

/** Rebrickable's English name of a part ("Tile 1 x 2 with Groove"), or '' when unknown. */
export function partName(ldraw) {
  return AVAILABILITY.names[ldraw] ?? '';
}

/** Source metadata of the availability table (where, when). */
export const AVAILABILITY_SOURCE = AVAILABILITY.source;
